#!/bin/bash
IFS=. read -r a b c d <<< "$1"; ip=$(( (a << 24) | (b << 16) | (c << 8) | d )); m=$(( (0xFFFFFFFF << (32 - $2)) & 0xFFFFFFFF )); f=$(( (ip & m) + 1 )); l=$(( (ip | (~m & 0xFFFFFFFF)) - 1 )); echo "$((f >> 24 & 255)).$((f >> 16 & 255)).$((f >> 8 & 255)).$((f & 255)) - $((l >> 24 & 255)).$((l >> 16 & 255)).$((l >> 8 & 255)).$((l & 255))"
